CREATE TABLE departments (deptname VARCHAR(20) PRIMARY KEY, deptaddr VARCHAR(20));
CREATE TABLE units (deptname VARCHAR(20) NOT NULL REFERENCES departments(deptname) ON DELETE CASCADE, unitid VARCHAR(20) NOT NULL, unitaddr VARCHAR(20), PRIMARY KEY (deptname, unitid));
CREATE TABLE users (deptname VARCHAR(20) NOT NULL, unitid VARCHAR(20) NOT NULL, userid VARCHAR(20) NOT NULL, useraddr VARCHAR(20), user_type VARCHAR(20) NOT NULL CHECK (user_type IN ('verified', 'unverified')), PRIMARY KEY (deptname, unitid, userid), UNIQUE (deptname, unitid, userid, user_type), FOREIGN KEY (deptname, unitid) REFERENCES units(deptname, unitid) ON DELETE CASCADE);
CREATE TABLE verified_users (deptname VARCHAR(20) NOT NULL, unitid VARCHAR(20) NOT NULL, userid VARCHAR(20) NOT NULL, user_type VARCHAR(20) NOT NULL DEFAULT 'verified' CHECK (user_type = 'verified'), pin VARCHAR(20), PRIMARY KEY (deptname, unitid, userid), FOREIGN KEY (deptname, unitid, userid, user_type) REFERENCES users(deptname, unitid, userid, user_type) ON DELETE CASCADE);
CREATE TABLE unverified_users (deptname VARCHAR(20) NOT NULL, unitid VARCHAR(20) NOT NULL, userid VARCHAR(20) NOT NULL, user_type VARCHAR(20) NOT NULL DEFAULT 'unverified' CHECK (user_type = 'unverified'), r3_deptname VARCHAR(20) NOT NULL, r3_unitid VARCHAR(20) NOT NULL, r3_userid VARCHAR(20) NOT NULL, PRIMARY KEY (deptname, unitid, userid), FOREIGN KEY (deptname, unitid, userid, user_type) REFERENCES users(deptname, unitid, userid, user_type) ON DELETE CASCADE, FOREIGN KEY (r3_deptname, r3_unitid, r3_userid) REFERENCES verified_users(deptname, unitid, userid));
